CURLcode close_curl_easy_handle(struct Curl_easy *data) {
    if (!data) {
        return CURLE_OK;
    }

    /* Clear timers associated with the handle */
    Curl_rem_time(data);

    /* Detach from a multi handle if it's part of one */
    if (data->multi) {
        Curl_remove_handle(data->multi, data);
    }

    /* Clean up multi handle if created */
    if (data->multi_owned) {
        Curl_multi_cleanup(data->multi);
    }

    /* Destroy timeout lists */
    Curl_safelist_free(data);

    /* Free allocated memory for states and configurations */
    Curl_ssl_free1(data);
    Curl_ssl_free2(data);
    Curl_cleanup_conncache(data);
    Curl_close_all(data);

    /* Close SSL sessions */
    Curl_ssl_close_all(data);

    /* Clean up redirect information */
    Curl_cleanup_single(data);

    /* Release resources related to the share and wildcard structures */
    if (data->share) {
        Curl_share_cleanup(data->share);
    }

    Curl_wildcard_dtor(data);

    /* Free the easy handle itself */
    Curl_free(data);

    return CURLE_OK;
}

CURLcode close_curl_easy_handle(struct Curl_easy *data) {
    if (!data) {
        return CURLE_OK;
    }

    /* Clear any timers associated with the handle */
    Curl_clean_timer(data);

